function DoubleRateTips:CheckUnLock()
    local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
    local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
    self.BtnList[3].interactable = isHavePrivilegeCard
    CfUtils.SetActive(self.ImgCircleLock3, not isHavePrivilegeCard)
    CfUtils.SetActive(self.ImgCircleOpen3, isHavePrivilegeCard)

    local unlockState = UIBattlingCtrlMgr:GetInstance():CheckUnLockStateOfPlayerSetting()
    self.BtnList[2].interactable = unlockState
    CfUtils.SetActive(self.ImgCircleLock2, not unlockState)
    CfUtils.SetActive(self.ImgCircleOpen2, unlockState)
end

function DoubleRateTips:SetSelect()
    local playerUID = UIBattlingCtrlMgr:GetInstance():GetPlayerUID()
    local originalGameSpeed = PlayerPrefsUtility.GetEncryptedInt(playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
    CfUtils.SetActive(self.Selected1, originalGameSpeed == 1)
    CfUtils.SetActive(self.Selected2, originalGameSpeed == 2)
    CfUtils.SetActive(self.Selected3, originalGameSpeed == 3)
end

function DoubleRateTips:OnClickTripleRate()
    local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
    local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))
    
    if not isHavePrivilegeCard then
        GameUtils.Toast(Constants.BATTLING_SETTING_TRIPLE_LOCK())
    else
        local playerUID = UIBattlingCtrlMgr:GetInstance():GetPlayerUID()
        local originalGameSpeed = PlayerPrefsUtility.GetEncryptedInt(playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
        if originalGameSpeed == 3 then
            --和之前倍速一样直接没反应
            return
        end
        self:SetGameSpeed(3, true)
        GameUtils.Toast(Constants.BATTLING_SETTING_GAME_TRIPLE())
        self:OnOut()
    end
end

function DoubleRateTips:OnClickDoubleRate()
    local unlockState = UIBattlingCtrlMgr:GetInstance():CheckUnLockStateOfPlayerSetting()
    if not unlockState then
        GameUtils.Toast(Constants.BATTLING_SETTING_DESCRIPTION())
    else
        local playerUID = UIBattlingCtrlMgr:GetInstance():GetPlayerUID()
        local originalGameSpeed = PlayerPrefsUtility.GetEncryptedInt(playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
        if originalGameSpeed == 2 then
            return
        end
        self:SetGameSpeed(2, true)
        GameUtils.Toast(Constants.BATTLING_SETTING_GAME_DOUBLE())
        self:OnOut()
    end
end

function DoubleRateTips:OnClickNormalRate()
    local playerUID = UIBattlingCtrlMgr:GetInstance():GetPlayerUID()
    local originalGameSpeed = PlayerPrefsUtility.GetEncryptedInt(playerUID .. Constants.PlayerPrefsType.BattleDoubleRateState, 0)
    if originalGameSpeed == 1 then
        return
    end
    self:SetGameSpeed(1, true)
    GameUtils.Toast(Constants.BATTLING_SETTING_GAME_NORMAL())
    self:OnOut()
end

function DoubleRateTips:SetGameSpeed(nowSpeed, save)
    UIBattleSettingMgr:SetDoubleRateState(nowSpeed, save)
    Events.Broadcast(Constants.EventNames.UIBattlingDoubleRateRunning, nowSpeed)
end

return DoubleRateTips